// Verify the live character menu portraits and home avatar, then restore route.
if(!UnityEditor.EditorApplication.isPlaying)throw new System.Exception("Play required");
var r=UnityEngine.Object.FindFirstObjectByType<EchoSphere.Runtime.EchoSphereRuntime>();var t=r.GetType();var f=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic;var route=t.GetField("_mainMenuPage",f);var original=route.GetValue(r);bool bg=UnityEngine.Application.runInBackground;int last=-1,frames=0,checks=0;var deadline=UnityEditor.EditorApplication.timeSinceStartup+40;UnityEditor.EditorApplication.CallbackFunction tick=null;
UnityEngine.Application.runInBackground=true;route.SetValue(r,System.Enum.Parse(route.FieldType,"Characters"));UnityEditor.SessionState.SetString("EchoApprovedCharacterUI","RUNNING");
void Finish(string result){UnityEditor.EditorApplication.update-=tick;route.SetValue(r,original);UnityEngine.Application.runInBackground=bg;UnityEditor.SessionState.SetString("EchoApprovedCharacterUI",Newtonsoft.Json.JsonConvert.SerializeObject(new{result,checks}));}
tick=()=>{try{if(UnityEditor.EditorApplication.timeSinceStartup>deadline)throw new System.Exception("Timeout");if(last==UnityEngine.Time.frameCount)return;last=UnityEngine.Time.frameCount;if(++frames<20)return;
var screen=UnityEngine.Object.FindFirstObjectByType<EchoSphere.Presentation.NativeCharacterScreen>();var doc=screen.GetComponent<UnityEngine.UIElements.UIDocument>();var portraits=UnityEngine.UIElements.UQueryExtensions.Query<UnityEngine.UIElements.Image>(doc.rootVisualElement,name:"character-portrait").ToList();if(portraits.Count!=10)throw new System.Exception("Expected ten portrait Images, got "+portraits.Count);checks++;foreach(var image in portraits){if(image.sprite==null)throw new System.Exception("Missing portrait Sprite");checks++;}
var home=UnityEngine.Object.FindFirstObjectByType<EchoSphere.Presentation.NativeMainMenuScreen>();var avatar=UnityEngine.UIElements.UQueryExtensions.Q<UnityEngine.UIElements.Image>(home.GetComponent<UnityEngine.UIElements.UIDocument>().rootVisualElement,"native-menu-character-portrait");if(avatar?.sprite==null)throw new System.Exception("Missing selected home avatar");checks++;Finish("PASS actual character menu: ten native portraits including locked previews, selected home avatar");}catch(System.Exception e){Finish("FAIL "+e);}};UnityEditor.EditorApplication.update+=tick;return "Started actual roster UI check";
